import java.util.Arrays;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        ExecutorService ioPool = Executors.newFixedThreadPool(4, namedFactory("cf-io"));
        try {
            CompletableFuture<Integer> userId = CompletableFuture.supplyAsync(() -> 7, ioPool);
            CompletableFuture<String> profile = userId.thenCompose(id ->
                    CompletableFuture.supplyAsync(() -> "user-" + id, ioPool));
            CompletableFuture<Integer> orderCount = userId.thenCompose(id ->
                    CompletableFuture.supplyAsync(() -> id - 4, ioPool));
            String summary = profile.thenCombine(orderCount,
                    (user, orders) -> user + ":orders=" + orders).join();
            System.out.println("summary=" + summary);
            assert "user-7:orders=3".equals(summary);

            CompletableFuture<String> a = CompletableFuture.supplyAsync(() -> "A", ioPool);
            CompletableFuture<String> b = CompletableFuture.supplyAsync(() -> "B", ioPool);
            CompletableFuture<String> c = CompletableFuture.supplyAsync(() -> "C", ioPool);
            List<String> all = CompletableFuture.allOf(a, b, c)
                    .thenApply(ignored -> Arrays.asList(a, b, c).stream()
                            .map(CompletableFuture::join)
                            .collect(Collectors.toList()))
                    .join();
            System.out.println("all=" + all);
            assert all.equals(Arrays.asList("A", "B", "C"));

            String fallback = CompletableFuture.<String>supplyAsync(() -> {
                throw new IllegalStateException("remote failed");
            }, ioPool).exceptionally(ex -> "fallback").join();
            System.out.println("fallback=" + fallback);
            assert "fallback".equals(fallback);

            AtomicBoolean observed = new AtomicBoolean(false);
            CompletableFuture<String> observedFailure = CompletableFuture.<String>supplyAsync(() -> {
                throw new IllegalArgumentException("bad data");
            }, ioPool).whenComplete((value, ex) -> observed.set(ex != null));
            try {
                observedFailure.join();
                throw new AssertionError("whenComplete should not hide the failure");
            } catch (CompletionException expected) {
                System.out.println("observed=" + observed.get()
                        + ", cause=" + expected.getCause().getMessage());
                assert observed.get();
            }

            String timed = CompletableFuture.supplyAsync(() -> {
                sleep(120);
                return "slow";
            }, ioPool).completeOnTimeout("timeout-fallback", 30, TimeUnit.MILLISECONDS).join();
            System.out.println("timeout=" + timed);
            assert "timeout-fallback".equals(timed);
        } finally {
            ioPool.shutdownNow();
        }
    }

    static ThreadFactory namedFactory(String prefix) {
        AtomicInteger index = new AtomicInteger();
        return runnable -> new Thread(runnable, prefix + "-" + index.incrementAndGet());
    }

    static void sleep(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
